const items = $input.all();

// 1. Fusionner les textes
const contenus = items
  .map(i => i.json.contenu)
  .filter(Boolean);

let messageFusionne = contenus.join(' [SUITE] ');

// 2. Récupérer les IDs pour la mise à jour
const idsToUpdate = items.map(i => i.json.id);

// 3. Infos client
const client = items[0].json.client;
// Extract phone: "Name : 225... @c.us" -> "225..."
const phone = client.split(' : ').pop().replace('@c.us', '');

return [
  {
    json: {
      message: messageFusionne,
      client: client,
      phone: phone,
      batchIds: idsToUpdate
    }
  }
];

